COUNTRIES = {}
for iso, spellings in COUNTRY_NAMES.items():
    for spelling in spellings:
        COUNTRIES[spelling] = iso

def country_query(text):
    words = text.strip().split()
    for count in range(min(5, len(words)-1), 0, -1):
        prefix = " ".join(words[:count]).lower()
        suffix = " ".join(words[-count:]).lower()
        if prefix in COUNTRIES:
            return " ".join(words[count:]), COUNTRIES[prefix]
        if suffix in COUNTRIES:
            return " ".join(words[:-count]), COUNTRIES[suffix]
    return text.strip(), ""

INITIAL = "g kk n d tt r m b pp s ss - j jj ch k t p h".split()
VOWEL = "a ae ya yae eo e yeo ye o wa wae oe yo u wo we wi yu eu ui i".split()
FINAL = [""] + "k k k n n n t l k m l l l p l m p p t t ng t t k t p t".split()
def latin_spelling(text):
    letters = []
    for char in text.lower():
        if "가" <= char <= "힣":
            index = ord(char)-44032
            letters.append(INITIAL[index//588].replace("-", "")+VOWEL[index//28%21]+FINAL[index%28])
        elif "a" <= char <= "z" or "0" <= char <= "9":
            letters.append(char)
        else:
            letters.append(ACCENTS.get(char, ""))
    return "".join(letters)

def sound_key(text):
    word = latin_spelling(text).replace("v","b").replace("ph","f").replace("r","l")
    out = ""
    for char in word:
        if not out.endswith(char):
            out += char
    return out

def place_probes(terms):
    probes = []
    for word in terms:
        if any("가" <= c <= "힣" for c in word):
            if sum(1 for c in word if "가" <= c <= "힣") < 3:
                continue
        elif any(ord(c)>127 and c.isalpha() and c not in ACCENTS for c in word):
            continue
        norm = sound_key(word)
        if len(norm)>=3 and norm not in probes:
            probes.append(norm)
    return probes[:12]

